59: function attack(){if(dead)return;let p=$('#player'),x=player.x,y=player.y;let fx=document.createElement('div');fx.className='projectile';fx.style.left=(x+30)+'px';fx.style.top=(y+25)+'px';arena.appendChild(fx);let angle=0;if(keys.ArrowRight||keys.d)angle=0;if(keys.ArrowLeft||keys.a)angle=Math.PI;if(keys.ArrowUp||keys.w)angle=-Math.PI/2;if(keys.ArrowDown||keys.s)angle=Math.PI/2;let vx=Math.cos(angle)*9,vy=Math.sin(angle)*9;let life=80;let timer=setInterval(()=>{let lx=parseFloat(fx.style.left)+vx,ly=parseFloat(fx.style.top)+vy;fx.style.left=lx+'px';fx.style.top=ly+'px';life--;for(let e of enemies){if(!e.isConnected)continue;let ex=parseFloat(e.style.left),ey=parseFloat(e.style.top);if(Math.abs(lx-ex)<30&&Math.abs(ly-ey)<30){let dmg=18+(panAttack?15:0);let hpv=+e.dataset.hp-dmg;e.dataset.hp=hpv;dmgText(ex,ey,'-'+dmg);fx.remove();clearInterval(timer);if(hpv<=0){let boss=e.classList.contains('boss');drop(ex,ey,boss);e.remove();enemies=enemies.filter(z=>z!==e);if(!enemies.length){if(boss)treasure();else{wave++;setTimeout(spawnWave,1200)}}}break}}if(life<=0){fx.remove();clearInterval(timer)}},16)}
