function moveStick(e){if(!stickActive)return;let r=stick.getBoundingClientRect(),point=e.touches?e.touches[0]:e,cx=r.left+r.width/2,cy=r.top+r.height/2;let dx=point.clientX-cx,dy=point.clientY-cy,len=Math.hypot(dx,dy)||1;let max=r.width*.32;if(len>max){dx=dx/len*max;dy=dy/len*max}stick.style.setProperty('--stick-x',dx+'px');stick.style.setProperty('--stick-y',dy+'px');stick.style.background=`radial-gradient(circle at ${50+dx/max*25}% ${50+dy/max*25}%,#ffd45c 0 18%,#17132155 19%)`;stickDX=dx/max;stickDY=dy/max}
stick.addEventListener('pointerdown',e=>{stickActive=true;stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',moveStick);stick.addEventListener('pointerup',()=>{stickActive=false;stickDX=0;stickDY=0;stick.style.background='#17132155'});stick.addEventListener('pointercancel',()=>{stickActive=false;stickDX=0;stickDY=0});
function gameLoop(){if(!dead){let mx=stickDX+(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0);let my=stickDY+(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);player.x+=mx*player.speed;player.y+=my*player.speed;player.x=Math.max(0,Math.min(arena.clientWidth-55,player.x));player.y=Math.max(55,Math.min(arena.clientHeight-55,player.y));placePlayer();for(let e of enemies){if(!e.isConnected)continue;let ex=parseFloat(e.style.left),ey=parseFloat(e.style.top);let dx=player.x-ex,dy=player.y-ey,d=Math.hypot(dx,dy)||1;if(d<260){let pace=e.classList.contains('boss')?1.15:.7;e.style.left=(ex+dx/d*pace)+'px';e.style.top=(ey+dy/d*pace)+'px'}if(d<38){hp-=.12*(e.classList.contains('boss')?3:1);updateHud();if(hp<=0)die()}}}requestAnimationFrame(gameLoop)}gameLoop();

